python
def ribbonRunsPeakTicket(line, k):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return max(out,default=0)


java
class Solution {
  public int ribbonRunsPeakTicket(String line, int k) {
    String a=line; List<Integer> out=new ArrayList<>();
    {for(int i=0;i<a.length();){int j=i+1;while(j<a.length()&&a.charAt(j)==a.charAt(i))j++;out.add(j-i);i=j;}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
